(window.V2_TALK=window.V2_TALK||{})["eglise"]={"eglise/eglise":[{"id":"V_eglise_bricolage_02","title":"Le ciel vert","premise":"Tom's painting has gone a strange color.","cefr":"A1","lines":[{"speaker":"Tom","fr":"Regarde mon dessin, Inès ! C'est l'église et le clocher.","en":"Look at my drawing, Inès! It's the church and the bell tower.","spans":[]},{"speaker":"Inès","fr":"Il est beau ! Mais pourquoi le ciel est vert ?","en":"It's lovely! But why is the sky green?","spans":[]},{"speaker":"Tom","fr":"Mon pinceau était sale…","en":"My brush was dirty…","spans":[]},{"speaker":"Inès","fr":"Il faut laver ton pinceau dans l'eau entre deux couleurs.","en":"You have to wash your brush in water between two colors.","spans":[]},{"speaker":"Tom","fr":"Bon, c'est un ciel vert. C'est de l'art moderne !","en":"Well, it's a green sky. It's modern art!","spans":[]},{"speaker":"Inès","fr":"Ha ha ! Tu ajoutes des pigeons sur le clocher ?","en":"Ha ha! Are you adding pigeons on the bell tower?","spans":[]}]},{"id":"V_eglise_bricolage_01","title":"Une écharpe pour M. Roux","premise":"Mrs. Roux teaches Léa to knit.","cefr":"A2","lines":[{"speaker":"Léa","fr":"Madame Roux, vous tricotez quoi ?","en":"Mrs. Roux, what are you knitting?","spans":[]},{"speaker":"Mme Roux","fr":"Une écharpe pour mon mari. Il a toujours froid quand il part au travail à quatre heures !","en":"A scarf for my husband. He's always cold when he leaves for work at four in the morning!","spans":[]},{"speaker":"Léa","fr":"Vous m'apprenez ?","en":"Will you teach me?","spans":[]},{"speaker":"Mme Roux","fr":"Avec plaisir. Prends ces deux aiguilles et cette pelote de laine rouge.","en":"With pleasure. Take these two needles and this ball of red wool.","spans":[]},{"speaker":"Léa","fr":"Comme ça ?","en":"Like this?","spans":[]},{"speaker":"Mme Roux","fr":"Oui, très bien ! Une maille, puis une autre…","en":"Yes, very good! One stitch, then another…","spans":[]},{"speaker":"Léa","fr":"C'est long ! Je vais faire un bonnet, c'est plus petit !","en":"It takes ages! I'll make a hat; it's smaller!","spans":[]},{"speaker":"Mme Roux","fr":"Ha ha ! Un bonnet, c'est une bonne idée pour commencer.","en":"Ha ha! A hat is a good idea to start with.","spans":[]}]},{"id":"V_eglise_bricolage_03","title":"Le chat et la pelote","premise":"Grandpa's knitting gets tangled by the parish cat.","cefr":"A2","lines":[{"speaker":"Papi Henri","fr":"Où est ma pelote de laine bleue ?","en":"Where's my ball of blue wool?","spans":[]},{"speaker":"Tom","fr":"Papi, tu tricotes, toi ?","en":"Grandpa, you knit?","spans":[]},{"speaker":"Papi Henri","fr":"Bien sûr ! J'ai appris avec ta grand-mère. Je te fais un bonnet.","en":"Of course! I learned with your grandmother. I'm making you a hat.","spans":[]},{"speaker":"Tom","fr":"Regarde, le chat joue avec ta pelote !","en":"Look, the cat's playing with your ball of wool!","spans":[]},{"speaker":"Papi Henri","fr":"Oh non, il y a de la laine partout !","en":"Oh no, there's wool everywhere!","spans":[]},{"speaker":"Tom","fr":"Attention à l'aiguille, elle est par terre.","en":"Careful with the needle, it's on the floor.","spans":[]},{"speaker":"Papi Henri","fr":"Merci. Bon… ton bonnet va peut-être devenir une écharpe.","en":"Thanks. Well… your hat might turn into a scarf.","spans":[]}]},{"id":"V_eglise_eglise_01","title":"Une bougie pour Mamie","premise":"Grandpa and Léa light a candle in the quiet church.","cefr":"A2","lines":[{"speaker":"Léa","fr":"Papi, pourquoi tu viens à l'église le mercredi ?","en":"Grandpa, why do you come to church on Wednesdays?","spans":[]},{"speaker":"Papi Henri","fr":"J'aime le silence ici. C'est un endroit de paix.","en":"I like the silence here. It's a peaceful place.","spans":[]},{"speaker":"Léa","fr":"Je peux allumer une bougie ?","en":"Can I light a candle?","spans":[[20,26,"fr_bougie_noun"]]},{"speaker":"Papi Henri","fr":"Oui. Mets d'abord une pièce dans le tronc.","en":"Yes. Put a coin in the offering box first.","spans":[]},{"speaker":"Léa","fr":"Voilà. Et j'allume ma bougie avec celle-là ?","en":"There. And I light my candle from that one?","spans":[[22,28,"fr_bougie_noun"]]},{"speaker":"Papi Henri","fr":"Oui, doucement. Tu penses à quelqu'un ?","en":"Yes, gently. Are you thinking of someone?","spans":[]},{"speaker":"Léa","fr":"À Mamie. Elle aimait beaucoup les fleurs de l'église.","en":"Of Grandma. She really loved the church flowers.","spans":[]},{"speaker":"Papi Henri","fr":"C'est vrai… Elle serait contente.","en":"That's true… She'd be happy.","spans":[]}]},{"id":"V_eglise_eglise_02","title":"L'orgue","premise":"Tom hears the organ and gets invited to the choir.","cefr":"A2","lines":[{"speaker":"Tom","fr":"Mon père, qui joue de l'orgue ?","en":"Father, who's playing the organ?","spans":[]},{"speaker":"Père Antoine","fr":"C'est madame Martin. Elle répète pour dimanche.","en":"It's Mrs. Martin. She's practicing for Sunday.","spans":[]},{"speaker":"Tom","fr":"C'est fort ! Toute l'église tremble !","en":"It's loud! The whole church is shaking!","spans":[]},{"speaker":"Père Antoine","fr":"Assieds-toi sur le banc et écoute. Tu aimes chanter ?","en":"Sit on the pew and listen. Do you like singing?","spans":[[19,23,"fr_banc_noun"]]},{"speaker":"Tom","fr":"Un peu. Mais je ne connais pas les chansons.","en":"A bit. But I don't know the songs.","spans":[]},{"speaker":"Père Antoine","fr":"Les paroles sont dans ce livre. Viens chanter avec la chorale samedi !","en":"The words are in this book. Come and sing with the choir on Saturday!","spans":[]},{"speaker":"Tom","fr":"D'accord, si Léa vient aussi.","en":"OK, if Léa comes too.","spans":[]}]},{"id":"V_eglise_eglise_03","title":"La petite souris","premise":"Léa spots a mouse living in the church.","cefr":"A2","lines":[{"speaker":"Léa","fr":"Mon père ! Il y a une souris sous le tapis !","en":"Father! There's a mouse under the rug!","spans":[]},{"speaker":"Père Antoine","fr":"Encore elle ? Elle habite ici depuis l'hiver dernier.","en":"Her again? She's lived here since last winter.","spans":[]},{"speaker":"Léa","fr":"Elle mange quoi ?","en":"What does she eat?","spans":[]},{"speaker":"Père Antoine","fr":"Les miettes des goûters du catéchisme, je crois… et parfois les fleurs de l'autel !","en":"Crumbs from the catechism-class snacks, I think… and sometimes the altar flowers!","spans":[]},{"speaker":"Léa","fr":"On ouvre la grande porte ? Elle peut partir dans le jardin.","en":"Should we open the big door? She can go out into the garden.","spans":[]},{"speaker":"Père Antoine","fr":"Bonne idée. Mais en silence, pour ne pas lui faire peur.","en":"Good idea. But quietly, so we don't frighten her.","spans":[]},{"speaker":"Léa","fr":"Regardez, elle sort ! Au revoir, petite souris !","en":"Look, she's going out! Goodbye, little mouse!","spans":[]}]},{"id":"V_eglise_paroisse_01","title":"La répétition","premise":"The children rehearse the Christmas show in the parish hall.","cefr":"A2","lines":[{"speaker":"Mme Petit","fr":"Bon, on répète le spectacle de Noël. Tom, tu as ton tambour ?","en":"Right, let's rehearse the Christmas show. Tom, do you have your drum?","spans":[]},{"speaker":"Tom","fr":"Oui ! Boum, boum, boum !","en":"Yes! Boom, boom, boom!","spans":[]},{"speaker":"Mme Petit","fr":"Pas si fort ! On n'entend plus la flûte d'Inès.","en":"Not so loud! We can't hear Inès's flute any more.","spans":[]},{"speaker":"Inès","fr":"Et Léa joue de la guitare, mais elle est trop timide.","en":"And Léa plays the guitar, but she's too shy.","spans":[]},{"speaker":"Léa","fr":"Je joue doucement…","en":"I play softly…","spans":[]},{"speaker":"Père Antoine","fr":"Moi, je vous accompagne au piano. Un, deux, trois…","en":"I'll accompany you on the piano. One, two, three…","spans":[]},{"speaker":"Mme Petit","fr":"Magnifique ! Et à la fin, tout le monde applaudit !","en":"Wonderful! And at the end, everyone claps!","spans":[]}]},{"id":"V_eglise_paroisse_02","title":"La collecte d'hiver","premise":"Mom brings warm things for families in need.","cefr":"A2","lines":[{"speaker":"Maman","fr":"Bonjour, mon père. J'apporte des couvertures pour la collecte.","en":"Hello, Father. I'm bringing blankets for the collection.","spans":[]},{"speaker":"Père Antoine","fr":"Merci beaucoup ! Elles sont pour les familles qui ont froid cet hiver.","en":"Thank you very much! They're for families who are cold this winter.","spans":[]},{"speaker":"Maman","fr":"Il y a aussi deux manteaux d'enfant. Tom ne les met plus.","en":"There are also two children's coats. Tom doesn't wear them any more.","spans":[]},{"speaker":"Père Antoine","fr":"Parfait. Posez tout sur la table, là-bas.","en":"Perfect. Put everything on the table over there.","spans":[]},{"speaker":"Maman","fr":"Oh, quelle pluie dehors ! Et j'ai oublié mon parapluie…","en":"Oh, what rain outside! And I've forgotten my umbrella…","spans":[]},{"speaker":"Père Antoine","fr":"Prenez celui-ci. Quelqu'un l'a oublié ici il y a un an !","en":"Take this one. Someone left it here a year ago!","spans":[]}]},{"id":"V_eglise_paroisse_03","title":"Les lanternes de décembre","premise":"The priest explains the Advent calendar and the December 8 lights.","cefr":"A2","lines":[{"speaker":"Léa","fr":"Mon père, c'est quoi, ce grand calendrier avec des petites portes ?","en":"Father, what's this big calendar with little doors?","spans":[]},{"speaker":"Père Antoine","fr":"C'est le calendrier de l'Avent. On ouvre une porte chaque jour jusqu'à Noël.","en":"It's the Advent calendar. You open one door every day until Christmas.","spans":[]},{"speaker":"Léa","fr":"Et ces lanternes ?","en":"And these lanterns?","spans":[]},{"speaker":"Père Antoine","fr":"Pour la procession du 8 décembre. Ce soir-là, il y a une lumière à toutes les fenêtres du village.","en":"For the procession on December 8. That evening, there's a light in every window in the village.","spans":[]},{"speaker":"Léa","fr":"Comme à Lyon !","en":"Like in Lyon!","spans":[]},{"speaker":"Père Antoine","fr":"Exactement. Certains prient, d'autres chantent, et après, tout le monde se retrouve ici.","en":"Exactly. Some people pray, others sing, and afterwards everyone meets up here.","spans":[]},{"speaker":"Léa","fr":"Je peux porter une lanterne ?","en":"Can I carry a lantern?","spans":[]},{"speaker":"Père Antoine","fr":"Bien sûr, si tu mets ton manteau : il fait froid le soir !","en":"Of course, if you put your coat on: it's cold in the evening!","spans":[]}]},{"id":"C_R_ch_nave","title":"La messe de minuit","premise":"A grandmother takes her grandson to midnight Mass on Christmas Eve.","cefr":"B2","lines":[{"speaker":"Mamie","fr":"Viens, Paul, on s'assoit sur ce banc, près de la statue de saint Joseph.","en":"Come on, Paul, let's sit on this pew, near the statue of Saint Joseph.","spans":[[32,36,"fr_banc_noun"],[49,55,"fr_statue_noun"]]},{"speaker":"Paul","fr":"Il y a beaucoup de monde !","en":"There are so many people!","spans":[]},{"speaker":"Mamie","fr":"Oui, à Noël, tous les fidèles viennent.","en":"Yes, at Christmas, all the faithful come.","spans":[[22,29,"fr_fidele_noun"]]},{"speaker":"Paul","fr":"Pourquoi il y a autant de bougies ?","en":"Why are there so many candles?","spans":[[26,33,"fr_bougie_noun"]]},{"speaker":"Mamie","fr":"Pour la lumière de Noël. Tu veux allumer un cierge ?","en":"For the light of Christmas. Do you want to light a candle?","spans":[[44,50,"fr_cierge_noun"]]},{"speaker":"Paul","fr":"Oui ! Pour Papi.","en":"Yes! For Grandpa.","spans":[]},{"speaker":"Mamie","fr":"C'est une belle idée. Regarde, le cortège des enfants de chœur arrive.","en":"That's a lovely idea. Look, the altar servers' procession is coming.","spans":[[34,41,"fr_cortege_noun"]]},{"speaker":"Paul","fr":"Et ce panier, c'est pour quoi ?","en":"And what's that basket for?","spans":[]},{"speaker":"Mamie","fr":"Pour la quête. Tiens, mets cette pièce.","en":"For the collection. Here, put this coin in.","spans":[[8,13,"fr_quete_noun"]]},{"speaker":"Paul","fr":"Mamie, à la maison, on mange à la chandelle ce soir ?","en":"Grandma, are we having dinner by candlelight at home tonight?","spans":[[34,43,"fr_chandelle_noun"]]},{"speaker":"Mamie","fr":"Bien sûr, c'est la tradition !","en":"Of course, it's tradition!","spans":[]}]}],"eglise/parvis":[{"id":"V_eglise_clocher_03","title":"Midi sonne","premise":"Tom and Léa count the bells to know when to go home.","cefr":"A1","lines":[{"speaker":"Léa","fr":"Écoute ! Les cloches sonnent.","en":"Listen! The bells are ringing.","spans":[[13,20,"fr_cloche_noun"]]},{"speaker":"Tom","fr":"On compte ? Un, deux, trois…","en":"Should we count? One, two, three…","spans":[]},{"speaker":"Léa","fr":"… onze, douze ! Il est midi.","en":"… eleven, twelve! It's noon.","spans":[]},{"speaker":"Tom","fr":"Maman a dit : à la maison quand ça sonne midi.","en":"Mom said: home when it strikes twelve.","spans":[]},{"speaker":"Léa","fr":"Vite, on court !","en":"Quick, let's run!","spans":[]},{"speaker":"Tom","fr":"Attends, je regarde l'horloge… Elle a cinq minutes de retard. On a le temps !","en":"Wait, let me look at the clock… It's five minutes slow. We've got time!","spans":[]},{"speaker":"Léa","fr":"Non, Tom ! Si elle retarde, il est déjà midi cinq !","en":"No, Tom! If it's slow, it's already five past twelve!","spans":[]}]},{"id":"V_eglise_clocher_01","title":"Monter au clocher","premise":"The priest takes the children up to see the bell.","cefr":"A2","lines":[{"speaker":"Père Antoine","fr":"Vous voulez voir la cloche ? Il faut monter cent vingt marches.","en":"Do you want to see the bell? You have to climb a hundred and twenty steps.","spans":[[20,26,"fr_cloche_noun"]]},{"speaker":"Tom","fr":"On y va ! Léa, le premier en haut a gagné !","en":"Let's go! Léa, first to the top wins!","spans":[]},{"speaker":"Père Antoine","fr":"Doucement, l'escalier est étroit !","en":"Slowly, the stairs are narrow!","spans":[]},{"speaker":"Léa","fr":"Ouf… on est arrivés. Oh, elle est énorme, la cloche !","en":"Phew… we're here. Oh, the bell is huge!","spans":[[45,51,"fr_cloche_noun"]]},{"speaker":"Père Antoine","fr":"Elle pèse une tonne, et elle a deux cents ans.","en":"It weighs a ton, and it's two hundred years old.","spans":[]},{"speaker":"Tom","fr":"Il y a plein de pigeons ici !","en":"There are loads of pigeons up here!","spans":[]},{"speaker":"Père Antoine","fr":"Oui, ce sont mes voisins. Ils ne paient pas de loyer !","en":"Yes, they're my neighbors. They don't pay rent!","spans":[]}]},{"id":"V_eglise_clocher_02","title":"L'horloge retarde","premise":"The mayor complains that the church clock is slow.","cefr":"A2","lines":[{"speaker":"Mme Lefort","fr":"Mon père, l'horloge de l'église a cinq minutes de retard.","en":"Father, the church clock is five minutes slow.","spans":[]},{"speaker":"Père Antoine","fr":"Encore ? Je l'ai réglée lundi !","en":"Again? I set it on Monday!","spans":[]},{"speaker":"Mme Lefort","fr":"Ce matin, les cloches ont sonné à huit heures cinq. Tout le village est arrivé en retard !","en":"This morning the bells rang at five past eight. The whole village was late!","spans":[[14,21,"fr_cloche_noun"]]},{"speaker":"Père Antoine","fr":"C'est une vieille horloge. Je vais demander à monsieur Blanc de la réparer.","en":"It's an old clock. I'll ask Mr. Blanc to repair it.","spans":[]},{"speaker":"Mme Lefort","fr":"Le garagiste ?","en":"The mechanic?","spans":[]},{"speaker":"Père Antoine","fr":"Oui ! Il répare tout : les voitures, les vélos… et les horloges.","en":"Yes! He repairs everything: cars, bikes… and clocks.","spans":[]}]},{"id":"C_R_ch_parvis","title":"La cathédrale du dimanche","premise":"Two tourists admire a cathedral as the bells start ringing.","cefr":"B2","lines":[{"speaker":"Émilie","fr":"Regarde cette cathédrale ! Le portail est magnifique.","en":"Look at that cathedral! The doorway is magnificent.","spans":[[14,24,"fr_cathedrale_noun"],[30,37,"fr_portail_noun"]]},{"speaker":"Thomas","fr":"Oui, toutes ces statues sculptées... Il a fallu des siècles pour construire cette église.","en":"Yes, all those carved statues... It took centuries to build this church.","spans":[[82,88,"fr_eglise_noun"]]},{"speaker":"Émilie","fr":"Tu entends ? Les cloches sonnent !","en":"Can you hear? The bells are ringing!","spans":[[17,24,"fr_cloche_noun"]]},{"speaker":"Thomas","fr":"C'est l'heure de la messe. Le son vient du clocher, à droite.","en":"It's time for Mass. The sound's coming from the bell tower, on the right.","spans":[[43,50,"fr_clocher_noun"]]},{"speaker":"Émilie","fr":"On peut monter dans la tour ?","en":"Can we go up the tower?","spans":[[23,27,"fr_tour_noun_f"]]},{"speaker":"Thomas","fr":"Oui, trois cents marches. La vue sur la ville est superbe.","en":"Yes, three hundred steps. The view over the town is superb.","spans":[]},{"speaker":"Émilie","fr":"Et cette petite chapelle sur le côté ?","en":"And that little chapel on the side?","spans":[[16,24,"fr_chapelle_noun"]]},{"speaker":"Thomas","fr":"Elle est plus ancienne que la cathédrale.","en":"It's older than the cathedral.","spans":[[30,40,"fr_cathedrale_noun"]]},{"speaker":"Émilie","fr":"Écoute, une clochette à l'intérieur. La messe commence.","en":"Listen, a little bell inside. Mass is starting.","spans":[]},{"speaker":"Thomas","fr":"On revient après pour la visite.","en":"We'll come back afterwards for the tour.","spans":[]}]}],"eglise/sanctuaire":[{"id":"V_eglise_sanctuaire_01","title":"La veille de la communion","premise":"The day before First Communion, Léa helps get the sanctuary ready.","cefr":"A2","lines":[{"speaker":"Léa","fr":"Père Antoine, demain c'est ma première communion !","en":"Father Antoine, tomorrow is my First Communion!","spans":[[39,48,"fr_communion_noun"]]},{"speaker":"Père Antoine","fr":"Je sais, Léa. Toute la paroisse prépare la messe.","en":"I know, Léa. The whole parish is getting the Mass ready.","spans":[[43,48,"fr_messe_noun"]]},{"speaker":"Tom","fr":"Regardez, il y a des lys partout sur l'autel !","en":"Look, there are lilies all over the altar!","spans":[[39,44,"fr_autel_noun"]]},{"speaker":"Léa","fr":"Et la sacristine compte les hosties pour demain.","en":"And the sacristan is counting the hosts for tomorrow.","spans":[[28,35,"fr_hostie_noun"]]},{"speaker":"Père Antoine","fr":"Moi, je répète mon homélie. Elle ne sera pas trop longue, promis.","en":"I'm rehearsing my homily. It won't be too long, I promise.","spans":[[19,26,"fr_homelie_noun"]]},{"speaker":"Tom","fr":"Qu'est-ce qu'il y a dans le gros livre doré ?","en":"What's in the big gold book?","spans":[]},{"speaker":"Père Antoine","fr":"C'est le lectionnaire, avec les lectures de chaque messe.","en":"It's the lectionary, with the readings for every Mass.","spans":[[9,21,"fr_lectionnaire_noun"],[51,56,"fr_messe_noun"]]},{"speaker":"Léa","fr":"Et la petite porte dorée, derrière l'autel ?","en":"And the little gold door behind the altar?","spans":[[37,42,"fr_autel_noun"]]},{"speaker":"Père Antoine","fr":"C'est le tabernacle. Demain, le calice brillera et le crucifix ouvrira la procession.","en":"That's the tabernacle. Tomorrow the chalice will shine and the crucifix will lead the procession.","spans":[[9,19,"fr_tabernacle_noun"],[32,38,"fr_calice_noun"],[54,62,"fr_crucifix_noun"]]}]},{"id":"C_R_ch_altar_02","title":"La première communion","premise":"A girl and her mother talk on the way home from her First Communion.","cefr":"B2","lines":[{"speaker":"Maman","fr":"Tu étais très belle dans ta robe blanche, ma chérie.","en":"You looked beautiful in your white dress, darling.","spans":[]},{"speaker":"Margaux","fr":"Merci ! J'avais peur de faire tomber l'hostie.","en":"Thank you! I was scared of dropping the host.","spans":[[39,45,"fr_hostie_noun"]]},{"speaker":"Maman","fr":"Tout s'est bien passé. C'était ta première communion, un grand jour !","en":"Everything went fine. It was your First Communion, a big day!","spans":[[43,52,"fr_communion_noun"]]},{"speaker":"Margaux","fr":"Le prêtre a dit que l'eucharistie, c'est le cœur de la messe.","en":"The priest said the Eucharist is the heart of Mass.","spans":[[55,60,"fr_messe_noun"]]},{"speaker":"Maman","fr":"C'est vrai. Tu as aimé la musique ?","en":"That's true. Did you like the music?","spans":[]},{"speaker":"Margaux","fr":"Oui ! Et les fleurs sur l'autel, sous le grand crucifix.","en":"Yes! And the flowers on the altar, under the big crucifix.","spans":[[26,31,"fr_autel_noun"],[47,55,"fr_crucifix_noun"]]},{"speaker":"Maman","fr":"Ta marraine les a apportées. C'était son offrande pour toi.","en":"Your godmother brought them. They were her gift for you.","spans":[]},{"speaker":"Margaux","fr":"On pourra aller au sanctuaire de Lourdes, cet été ?","en":"Can we go to the shrine at Lourdes this summer?","spans":[]},{"speaker":"Maman","fr":"Oui, avec Mamie. Elle en rêve !","en":"Yes, with Grandma. She's dreaming of it!","spans":[]}]},{"id":"C_R_ch_altar_02_demo","title":"Servir la messe","premise":"The sacristan prepares a new altar server before Sunday Mass.","cefr":"B2","lines":[{"speaker":"le sacristain","fr":"Bienvenue, Jules. Tu sers la messe pour la première fois ?","en":"Welcome, Jules. Is this your first time serving at Mass?","spans":[[29,34,"fr_messe_noun"]]},{"speaker":"Jules","fr":"Oui, je suis un peu stressé.","en":"Yes, I'm a bit nervous.","spans":[]},{"speaker":"le sacristain","fr":"Ne t'inquiète pas. Tu restes près de l'autel.","en":"Don't worry. You stay near the altar.","spans":[[39,44,"fr_autel_noun"]]},{"speaker":"Jules","fr":"Et pendant l'offrande, je fais quoi ?","en":"And during the offertory, what do I do?","spans":[]},{"speaker":"le sacristain","fr":"Tu apportes le pain et le vin au prêtre.","en":"You bring the bread and wine to the priest.","spans":[]},{"speaker":"Jules","fr":"Les hosties sont où ?","en":"Where are the hosts?","spans":[[4,11,"fr_hostie_noun"]]},{"speaker":"le sacristain","fr":"Dans cette boîte. Elles sont pour l'eucharistie.","en":"In this box. They're for the Eucharist.","spans":[]},{"speaker":"Jules","fr":"Je m'incline devant le crucifix en entrant ?","en":"Do I bow to the crucifix when I come in?","spans":[[23,31,"fr_crucifix_noun"]]},{"speaker":"le sacristain","fr":"Oui, et tu marches calmement dans le sanctuaire.","en":"Yes, and you walk calmly in the sanctuary.","spans":[]},{"speaker":"Jules","fr":"Et à la communion ?","en":"And at communion?","spans":[[8,17,"fr_communion_noun"]]},{"speaker":"le sacristain","fr":"Tu tiens le plateau. Tu vas très bien t'en sortir.","en":"You hold the plate. You'll do very well.","spans":[]}]}],"eglise/crypte":[{"id":"V_eglise_crypte_01","title":"La visite de la crypte","premise":"On Heritage Day, Tom and Léa visit the old crypt under the church.","cefr":"A2","lines":[{"speaker":"Tom","fr":"Chut… on descend dans la crypte. Il fait frais ici !","en":"Shh… we're going down into the crypt. It's cool down here!","spans":[[25,31,"fr_crypte_noun"]]},{"speaker":"Léa","fr":"Regarde cette vieille canne dans la niche. C'est une relique ?","en":"Look at that old staff in the niche. Is it a relic?","spans":[[53,60,"fr_relique_noun"]]},{"speaker":"Père Antoine","fr":"Oui, c'est le bâton de la sainte du village. Elle est sur la fresque, avec l'agneau.","en":"Yes, it's the walking staff of the village saint. She's on the fresco, with the lamb.","spans":[[26,32,"fr_sainte_noun"]]},{"speaker":"Tom","fr":"Pourquoi la petite lampe rouge est allumée ?","en":"Why is the little red lamp lit?","spans":[]},{"speaker":"Père Antoine","fr":"C'est une flamme éternelle : on ne l'éteint jamais.","en":"It's an eternal flame: we never put it out.","spans":[[17,26,"fr_eternel_adj"]]},{"speaker":"Léa","fr":"Les gens viennent ici pour prier ?","en":"Do people come here to pray?","spans":[[27,32,"fr_prier_verb"]]},{"speaker":"Père Antoine","fr":"Oui, et pour honorer les saints. Ils apportent des fleurs devant le reliquaire.","en":"Yes, and to honor the saints. They bring flowers to the reliquary.","spans":[[13,20,"fr_honorer_verb"],[68,78,"fr_reliquaire_noun"]]},{"speaker":"Léa","fr":"Et cette longue tombe en pierre, avec la statue couchée qui porte une mitre ?","en":"And that long stone tomb, with the statue lying down and wearing a miter?","spans":[]},{"speaker":"Père Antoine","fr":"C'est la tombe d'un archevêque. Il repose ici en paix depuis trois cents ans.","en":"That's the tomb of an archbishop. He has rested here in peace for three hundred years.","spans":[[20,30,"fr_archeveque_noun"]]},{"speaker":"Tom","fr":"Et le jeune homme sculpté sur le pilier, avec la palme ?","en":"And the young man carved on the pillar, with the palm branch?","spans":[]},{"speaker":"Père Antoine","fr":"C'est un martyr, un saint très ancien. Allez, une petite bénédiction pour vous deux avant de remonter !","en":"He's a martyr, a very old saint. Come on, a little blessing for you two before we go back up!","spans":[[9,15,"fr_martyr_noun"],[57,68,"fr_benediction_noun"]]}]},{"id":"C_R_ch_crypt","title":"La crypte de la basilique","premise":"A guide shows visitors the crypt under an old basilica.","cefr":"C1","lines":[{"speaker":"le guide","fr":"Nous descendons maintenant dans la crypte. Attention aux marches.","en":"We're now going down into the crypt. Mind the steps.","spans":[[35,41,"fr_crypte_noun"]]},{"speaker":"une visiteuse","fr":"Il fait frais ! C'est très ancien ?","en":"It's cool! Is it very old?","spans":[]},{"speaker":"le guide","fr":"Neuvième siècle. Ici repose sainte Geneviève, une martyre selon la tradition locale.","en":"Ninth century. Saint Genevieve lies here, a martyr according to local tradition.","spans":[[28,34,"fr_sainte_noun"]]},{"speaker":"une visiteuse","fr":"Et cette petite boîte dorée ?","en":"And that little gold box?","spans":[]},{"speaker":"le guide","fr":"C'est une relique. Les pèlerins viennent la voir depuis mille ans.","en":"That's a relic. Pilgrims have been coming to see it for a thousand years.","spans":[[10,17,"fr_relique_noun"]]},{"speaker":"une visiteuse","fr":"Les gens étaient enterrés ici ?","en":"Were people buried here?","spans":[]},{"speaker":"le guide","fr":"Les moines, oui. Les autres, au cimetière derrière l'église.","en":"The monks, yes. Everyone else in the cemetery behind the church.","spans":[]},{"speaker":"une visiteuse","fr":"Sur cette pierre, il y a une inscription.","en":"There's an inscription on this stone.","spans":[]},{"speaker":"le guide","fr":"« Repos éternel ». Le prêtre donne une bénédiction ici chaque premier novembre.","en":"\"Eternal rest\". The priest gives a blessing here every first of November.","spans":[[8,15,"fr_eternel_adj"],[39,50,"fr_benediction_noun"]]},{"speaker":"une visiteuse","fr":"C'est un lieu très calme. On sent qu'il est saint.","en":"It's a very peaceful place. You can feel it's holy.","spans":[]}]}],"eglise/confessionnal":[{"id":"V_eglise_confessionnal_01","title":"Le pot cassé","premise":"Tom breaks a flowerpot in the side aisle and has to own up.","cefr":"A2","lines":[{"speaker":"Tom","fr":"Oh non… j'ai cassé le pot de fleurs près du confessionnal.","en":"Oh no… I broke the flowerpot near the confessional.","spans":[[44,57,"fr_confessionnal_noun"]]},{"speaker":"Mme Roux","fr":"Tu as l'air vraiment désolé. Je vois ta contrition, Tom.","en":"You look truly sorry. I can see your contrition, Tom.","spans":[[40,50,"fr_contrition_noun"]]},{"speaker":"Tom","fr":"Vous pouvez me pardonner ?","en":"Can you forgive me?","spans":[[15,24,"fr_pardonner_verb"]]},{"speaker":"Mme Roux","fr":"Bien sûr. Merci pour ta confession. On va en planter un autre.","en":"Of course. Thank you for owning up. We'll plant another one.","spans":[[24,34,"fr_confession_noun"]]},{"speaker":"Léa","fr":"Et moi, j'ai mangé une pêche du panier… C'est un péché ?","en":"And I ate a peach from the basket… Is that a sin?","spans":[[49,54,"fr_peche_noun_2"]]},{"speaker":"Mme Roux","fr":"Un tout petit, Léa ! Le peintre aussi a fait une erreur : regarde, il fait un repentir sur son tableau.","en":"A very small one, Léa! The painter made a mistake too: look, he's painting over it on his picture.","spans":[[78,86,"fr_repentir_noun"]]},{"speaker":"Tom","fr":"Et les deux petits frères là-bas se sont disputés, et maintenant ils s'embrassent.","en":"And the two little brothers over there had a fight, and now they're hugging.","spans":[]},{"speaker":"Mme Roux","fr":"C'est la réconciliation. Et la dame qui réchauffe le chaton, c'est la pitié.","en":"That's reconciliation. And the lady warming up the kitten, that's pity.","spans":[[9,23,"fr_reconciliation_noun"],[70,75,"fr_pitie_noun"]]}]},{"id":"C_R_ch_confessional","title":"La réconciliation","premise":"Two sisters reconcile after an argument, and one talks about going to confession.","cefr":"C1","lines":[{"speaker":"Anne","fr":"Marie, je suis désolée pour hier. J'ai dit des choses méchantes.","en":"Marie, I'm sorry about yesterday. I said nasty things.","spans":[]},{"speaker":"Marie","fr":"Moi aussi. On a toutes les deux exagéré.","en":"Me too. We both went too far.","spans":[]},{"speaker":"Anne","fr":"Je suis allée me confesser ce matin.","en":"I went to confession this morning.","spans":[]},{"speaker":"Marie","fr":"Ah oui ? Tu as parlé de notre dispute dans le confessionnal ?","en":"Really? Did you talk about our argument in the confessional?","spans":[[46,59,"fr_confessionnal_noun"]]},{"speaker":"Anne","fr":"Oui. Le prêtre a parlé de la miséricorde de Dieu et du repentir.","en":"Yes. The priest talked about God's mercy and repentance.","spans":[[55,63,"fr_repentir_noun"]]},{"speaker":"Marie","fr":"Et tu as eu l'absolution ?","en":"And did you get absolution?","spans":[]},{"speaker":"Anne","fr":"Oui. Il m'a dit que la colère n'est pas un si grand péché, mais qu'il faut faire la paix.","en":"Yes. He told me anger isn't such a big sin, but that you have to make peace.","spans":[[52,57,"fr_peche_noun_2"]]},{"speaker":"Marie","fr":"Alors, c'est notre réconciliation !","en":"Then this is our reconciliation!","spans":[[19,33,"fr_reconciliation_noun"]]},{"speaker":"Anne","fr":"Exactement. Pitié, plus de disputes pour des histoires de vêtements !","en":"Exactly. Please, no more arguments about clothes!","spans":[[12,17,"fr_pitie_noun"]]},{"speaker":"Marie","fr":"Promis ! Je te rends ton pull.","en":"Promise! I'll give you your sweater back.","spans":[]},{"speaker":"Anne","fr":"Merci ! Cette confession m'a fait du bien.","en":"Thanks! That confession did me good.","spans":[[14,24,"fr_confession_noun"]]}]},{"id":"C_R_ch_confessional_demo","title":"Se préparer à la confession","premise":"A teenager asks the parish priest how to prepare for confession.","cefr":"C1","lines":[{"speaker":"Théo","fr":"Mon père, je voudrais me confesser, mais j'ai peur.","en":"Father, I'd like to go to confession, but I'm scared.","spans":[]},{"speaker":"le père Martin","fr":"N'aie pas peur. La confession, c'est un moment de réconciliation.","en":"Don't be afraid. Confession is a moment of reconciliation.","spans":[[19,29,"fr_confession_noun"],[50,64,"fr_reconciliation_noun"]]},{"speaker":"Théo","fr":"Je dois dire tous mes péchés ?","en":"Do I have to tell all my sins?","spans":[[22,28,"fr_peche_noun_2"]]},{"speaker":"le père Martin","fr":"Ceux que tu regrettes. Le repentir sincère compte beaucoup.","en":"The ones you regret. Sincere repentance matters a lot.","spans":[[26,34,"fr_repentir_noun"]]},{"speaker":"Théo","fr":"Et après ?","en":"And afterwards?","spans":[]},{"speaker":"le père Martin","fr":"Je te donne l'absolution. Dieu est miséricorde.","en":"I give you absolution. God is mercy.","spans":[]},{"speaker":"Théo","fr":"On se met où ?","en":"Where do we go?","spans":[]},{"speaker":"le père Martin","fr":"Dans le confessionnal, là-bas.","en":"In the confessional, over there.","spans":[[8,21,"fr_confessionnal_noun"]]},{"speaker":"Théo","fr":"Merci, mon père. Ayez pitié de mon trac !","en":"Thank you, Father. Take pity on my nerves!","spans":[[22,27,"fr_pitie_noun"]]},{"speaker":"le père Martin","fr":"Ha ha ! Tout ira bien.","en":"Ha ha! It'll be fine.","spans":[]}]}],"eglise/baptistere":[{"id":"V_eglise_baptistere_01","title":"Le baptême de Chloé","premise":"The family gathers for baby Chloé's baptism, and the godfather is late.","cefr":"A2","lines":[{"speaker":"Inès","fr":"C'est le baptême de ma petite cousine Chloé aujourd'hui !","en":"It's my little cousin Chloé's baptism today!","spans":[[9,16,"fr_bapteme_noun"]]},{"speaker":"Maman","fr":"Et sa marraine arrive toute mouillée : il pleut dehors !","en":"And her godmother is arriving soaking wet: it's raining outside!","spans":[[6,14,"fr_marraine_noun"]]},{"speaker":"Père Antoine","fr":"Approchez-vous des fonts baptismaux. L'eau est prête.","en":"Come over to the font. The water is ready.","spans":[[19,35,"fr_fonts_baptismaux_noun"]]},{"speaker":"Inès","fr":"Qu'est-ce qu'il y a dans le petit pot en argent ?","en":"What's in the little silver jar?","spans":[]},{"speaker":"Père Antoine","fr":"C'est le saint chrême, une huile parfumée. Ce n'est pas de la crème pour le chat !","en":"It's the holy chrism, a scented oil. It's not cream for the cat!","spans":[[15,21,"fr_chreme_noun"]]},{"speaker":"Papi Henri","fr":"Mais où est le parrain ? On ne peut pas commencer sans lui.","en":"But where is the godfather? We can't start without him.","spans":[[15,22,"fr_parrain_noun"]]},{"speaker":"Maman","fr":"Le voilà ! Il a couru avec le cierge.","en":"Here he is! He ran all the way with the candle.","spans":[]},{"speaker":"Inès","fr":"Après, on va célébrer avec des dragées !","en":"Afterward we'll celebrate with sugared almonds!","spans":[[13,21,"fr_celebrer_verb"]]}]},{"id":"C_R_ch_baptistery","title":"Le baptême du petit Léo","premise":"Two friends talk about being godparents at a baby's baptism.","cefr":"C2","lines":[{"speaker":"Clara","fr":"Tu as vu ? Sarah m'a demandé d'être la marraine de Léo !","en":"Did you see? Sarah asked me to be Léo's godmother!","spans":[[39,47,"fr_marraine_noun"]]},{"speaker":"Maxime","fr":"Félicitations ! Et moi, je suis le parrain.","en":"Congratulations! And I'm the godfather.","spans":[[35,42,"fr_parrain_noun"]]},{"speaker":"Clara","fr":"Super ! Le baptême, c'est le mois prochain, à l'église Saint-Jean.","en":"Great! The baptism is next month, at Saint-Jean church.","spans":[[11,18,"fr_bapteme_noun"]]},{"speaker":"Maxime","fr":"Il y a un très vieux baptistère en pierre, là-bas.","en":"There's a very old stone baptistery there.","spans":[[21,31,"fr_baptistere_noun"]]},{"speaker":"Clara","fr":"On doit faire quelque chose pendant le sacrement ?","en":"Do we have to do anything during the sacrament?","spans":[]},{"speaker":"Maxime","fr":"Oui, on tient le bébé, et le prêtre fait l'onction avec l'huile.","en":"Yes, we hold the baby, and the priest does the anointing with the oil.","spans":[]},{"speaker":"Clara","fr":"Et après ?","en":"And afterwards?","spans":[]},{"speaker":"Maxime","fr":"On s'occupe de notre filleul toute sa vie ! Pour sa confirmation, par exemple.","en":"We look after our godson all his life! For his confirmation, for example.","spans":[]},{"speaker":"Clara","fr":"C'est une grande responsabilité.","en":"It's a big responsibility.","spans":[]},{"speaker":"Maxime","fr":"Oui, mais une belle !","en":"Yes, but a nice one!","spans":[]}]}],"eglise/cimetiere":[{"id":"V_eglise_cimetiere_01","title":"Des fleurs pour Mamie","premise":"Grandpa and Léa bring flowers to Grandma's grave on a sunny Sunday morning.","cefr":"A2","lines":[{"speaker":"Léa","fr":"Papi, il fait beau au cimetière ce matin.","en":"Grandpa, it's lovely in the churchyard this morning.","spans":[[22,31,"fr_cimetiere_noun"]]},{"speaker":"Papi Henri","fr":"Oui. Viens, on apporte ces fleurs sur la tombe de Mamie.","en":"Yes. Come on, let's take these flowers to Grandma's grave.","spans":[[41,46,"fr_tombe_noun"]]},{"speaker":"Léa","fr":"Le monsieur nettoie une vieille pierre tombale avec une brosse.","en":"The man is cleaning an old headstone with a brush.","spans":[[32,46,"fr_pierre_tombale_noun"]]},{"speaker":"Papi Henri","fr":"Il enlève la mousse pour qu'on puisse lire l'épitaphe.","en":"He's removing the moss so people can read the epitaph.","spans":[[45,53,"fr_epitaphe_noun"]]},{"speaker":"Léa","fr":"Et la petite maison avec du lierre, c'est quoi ?","en":"And the little house with ivy, what is it?","spans":[]},{"speaker":"Papi Henri","fr":"C'est un caveau de famille. Et la grande croix près de la grille, c'est le calvaire.","en":"It's a family vault. And the big cross by the gate is the calvary.","spans":[[9,15,"fr_caveau_noun"],[75,83,"fr_calvaire_noun"]]},{"speaker":"Léa","fr":"Mamie aimait les fleurs roses. Elle serait contente.","en":"Grandma loved pink flowers. She'd be happy.","spans":[]},{"speaker":"Papi Henri","fr":"Oui, ma chérie. Elle serait très contente.","en":"Yes, sweetheart. She'd be very happy.","spans":[]}]}],"eglise/choeur":[{"id":"V_eglise_choeur_01","title":"La messe vue du chœur","premise":"Tom sings in the choir for the first time, and Léa watches Sunday Mass from the choir stalls.","cefr":"B1","lines":[{"speaker":"Tom","fr":"Léa, je chante dans le chœur aujourd'hui ! J'ai un peu peur.","en":"Léa, I'm singing in the choir today! I'm a little scared.","spans":[[23,28,"fr_choeur_noun"]]},{"speaker":"Léa","fr":"Ne t'inquiète pas. L'orgue joue si fort que personne ne t'entendra !","en":"Don't worry. The organ plays so loud that nobody will hear you!","spans":[[21,26,"fr_orgue_noun"]]},{"speaker":"Mme Petit","fr":"Allez, les enfants, avec cœur ! Je vous exhorte à chanter bien fort.","en":"Come on, children, with heart! I urge you to sing out loud.","spans":[[40,47,"fr_exhorter_verb"]]},{"speaker":"Léa","fr":"Pourquoi Monsieur Verbe balance cette boîte en cuivre au bout des chaînes ?","en":"Why is Monsieur Verbe swinging that brass box on chains?","spans":[]},{"speaker":"Mme Petit","fr":"Il encense l'autel. L'encens, c'est une prière qui monte vers le ciel.","en":"He's incensing the altar. Incense is a prayer that rises to the sky.","spans":[[3,10,"fr_encenser_verb"]]},{"speaker":"Tom","fr":"Et la fille avec le panier de pain et de pommes ?","en":"And the girl with the basket of bread and apples?","spans":[]},{"speaker":"Mme Petit","fr":"C'est l'offrande pour la banque alimentaire. Ensuite, à l'offertoire, on apporte les hosties à l'autel.","en":"It's the offering for the food bank. Then, at the offertory, the hosts are brought to the altar.","spans":[[8,16,"fr_offrande_noun"],[58,68,"fr_offertoire_noun"]]},{"speaker":"Léa","fr":"Et le monsieur en pull gris, c'est un prêtre ?","en":"And the man in the gray sweater, is he a priest?","spans":[]},{"speaker":"Mme Petit","fr":"Non, c'est un laïc. Il lit la première lecture. La bannière verte, c'est la couleur liturgique du dimanche ordinaire.","en":"No, he's a layman. He reads the first reading. The green banner is the liturgical color of ordinary Sundays.","spans":[[14,18,"fr_laic_noun"],[84,94,"fr_liturgique_adj"]]},{"speaker":"Tom","fr":"Chut ! C'est la consécration. Après, on chante le Gloria pour glorifier Dieu.","en":"Shh! It's the consecration. Afterward we sing the Gloria to glorify God.","spans":[[16,28,"fr_consecration_noun"],[62,71,"fr_glorifier_verb"]]},{"speaker":"Léa","fr":"Toute la liturgie est en musique aujourd'hui. Bravo, Tom !","en":"The whole liturgy is in music today. Well done, Tom!","spans":[[9,17,"fr_liturgie_noun"]]}]}],"eglise/tresor":[{"id":"V_eglise_tresor_01","title":"Le grand nettoyage du trésor","premise":"Inès helps on restoration day in the church treasury, and Monsieur Verbe has a little accident.","cefr":"B1","lines":[{"speaker":"Inès","fr":"Que de trésors ! Qu'est-ce que vous essuyez, madame ?","en":"So many treasures! What are you drying, ma'am?","spans":[]},{"speaker":"Mme Lefort","fr":"La patène, la petite assiette dorée pour l'hostie. Et la sœur ferme la custode.","en":"The paten, the little gold plate for the host. And the sister is closing the pyx.","spans":[[3,9,"fr_patene_noun"],[71,78,"fr_custode_noun"]]},{"speaker":"Père Antoine","fr":"La custode sert à porter la communion aux malades.","en":"The pyx is used to take communion to the sick.","spans":[[3,10,"fr_custode_noun"]]},{"speaker":"Inès","fr":"Regardez ! Le bijoutier tient une coupe dorée avec un couvercle.","en":"Look! The jeweler is holding a gold cup with a lid.","spans":[]},{"speaker":"Père Antoine","fr":"C'est le ciboire. Et le relieur répare le vieux missel, le livre de la messe.","en":"That's the ciborium. And the bookbinder is repairing the old missal, the Mass book.","spans":[[9,16,"fr_ciboire_noun"],[48,54,"fr_missel_noun"]]},{"speaker":"Inès","fr":"Pourquoi il y a un monsieur sur l'échelle ?","en":"Why is there a man on the ladder?","spans":[]},{"speaker":"Mme Lefort","fr":"Il repeint le retable, derrière l'autel. Et Monsieur Verbe consacre toute sa journée à l'ambon !","en":"He's repainting the altarpiece behind the altar. And Monsieur Verbe is devoting his whole day to the ambo!","spans":[[14,21,"fr_retable_noun"],[59,67,"fr_consacrer_verb"],[89,94,"fr_ambon_noun"]]},{"speaker":"Inès","fr":"Oh, Monsieur Verbe a fait tomber le petit ange en plâtre ! Il se cache la bouche. Il culpabilise !","en":"Oh, Monsieur Verbe knocked over the little plaster angel! He's covering his mouth. He feels guilty!","spans":[[85,96,"fr_culpabiliser_verb"]]},{"speaker":"Père Antoine","fr":"Ne culpabilise pas, il n'est pas cassé. Regarde plutôt ce mime qui peint une auréole dorée sur le roi en bois : il le sanctifie !","en":"Don't feel guilty, it's not broken. Look instead at that mime painting a gold halo on the wooden king: he's making him a saint!","spans":[[3,14,"fr_culpabiliser_verb"],[118,127,"fr_sanctifier_verb"]]},{"speaker":"Mme Lefort","fr":"Et ma bannière eucharistique, avec le blé et les raisins ? Elle sera finie ce soir.","en":"And my Eucharistic banner, with the wheat and grapes? It'll be finished tonight.","spans":[[15,28,"fr_eucharistique_adj"]]},{"speaker":"Inès","fr":"Le mime en béret vert a converti une caisse en bibliothèque. Et celui-là lève les deux pouces : il prône tous les trésors !","en":"The mime in the green beret turned a crate into a bookshelf. And that one is giving two thumbs up: he's singing the praises of all the treasures!","spans":[[22,32,"fr_convertir_verb"],[99,104,"fr_proner_verb"]]}]}],"eglise/misericorde":[{"id":"V_eglise_misericorde_01","title":"Le pot de biscuits","premise":"An evening in the little Mercy chapel: Tom watches people pray, and Monsieur Verbe owns up to something.","cefr":"B1","lines":[{"speaker":"Tom","fr":"Papi, il fait sombre ici. Il y a seulement des bougies.","en":"Grandpa, it's dark in here. There are only candles.","spans":[]},{"speaker":"Papi Henri","fr":"C'est la chapelle de la Miséricorde. Regarde le tableau : le berger libère le petit agneau des ronces.","en":"It's the Mercy chapel. Look at the painting: the shepherd frees the little lamb from the brambles.","spans":[[24,35,"fr_misericorde_noun"]]},{"speaker":"Tom","fr":"La petite flamme de la fille est à la merci du courant d'air !","en":"The girl's little flame is at the mercy of the draft!","spans":[[38,43,"fr_merci_noun_f"]]},{"speaker":"Papi Henri","fr":"Le vieux monsieur donne son écharpe et un sandwich au jeune homme. Il est miséricordieux.","en":"The old man is giving his scarf and a sandwich to the young man. He's merciful.","spans":[[74,88,"fr_misericordieux_adj"]]},{"speaker":"Tom","fr":"Et là, le prêtre lève la main sur le monsieur à genoux ?","en":"And there, is the priest raising his hand over the kneeling man?","spans":[]},{"speaker":"Père Antoine","fr":"Oui, je lui donne l'absolution. Et la dame au foulard fait sa pénitence : elle prie.","en":"Yes, I'm giving him absolution. And the lady in the headscarf is doing her penance: she's praying.","spans":[[20,30,"fr_absolution_noun"],[62,71,"fr_penitence_noun"]]},{"speaker":"Tom","fr":"Le grand soleil en or sur l'autel, c'est quoi ?","en":"The big gold sun on the altar, what is it?","spans":[]},{"speaker":"Père Antoine","fr":"L'ostensoir. On vient adorer devant lui. La lumière de la fenêtre est presque divine ce soir.","en":"The monstrance. People come to worship before it. The light from the window is almost divine tonight.","spans":[[2,11,"fr_ostensoir_noun"],[22,28,"fr_adorer_verb"],[78,84,"fr_divin_adj"]]},{"speaker":"Papi Henri","fr":"La dame près des bougies prie pour les âmes du purgatoire.","en":"The lady by the candles is praying for the souls in purgatory.","spans":[[47,57,"fr_purgatoire_noun"]]},{"speaker":"Tom","fr":"Et Monsieur Verbe a des miettes partout ! Il confesse qu'il a mangé tous les biscuits !","en":"And Monsieur Verbe has crumbs everywhere! He's confessing that he ate all the cookies!","spans":[[45,53,"fr_confesser_verb"]]},{"speaker":"Père Antoine","fr":"Alors je l'absous. Son ami efface déjà l'ardoise !","en":"Then I absolve him. His friend is already wiping the slate clean!","spans":[[11,17,"fr_absoudre_verb"]]}]}],"eglise/salle":[{"id":"V_eglise_salle_01","title":"Le samedi du caté","premise":"Saturday catechism class in the parish hall: Léa prepares her confirmation and the little ones learn about the sacraments.","cefr":"B1","lines":[{"speaker":"Sophie","fr":"Bonjour tout le monde ! Aujourd'hui, on parle des sept sacrements. Comptez les bougies sur la bannière !","en":"Hello everyone! Today we're talking about the seven sacraments. Count the candles on the banner!","spans":[[55,65,"fr_sacrement_noun"]]},{"speaker":"Léa","fr":"Une, deux, trois… sept ! Et moi, je prépare ma confirmation.","en":"One, two, three… seven! And I'm getting ready for my confirmation.","spans":[[47,59,"fr_confirmation_noun"]]},{"speaker":"Père Antoine","fr":"Le premier, c'est le baptême. Regarde, Monsieur Verbe montre comment baptiser la poupée.","en":"The first one is baptism. Look, Monsieur Verbe is showing how to baptize the doll.","spans":[[69,77,"fr_baptiser_verb"]]},{"speaker":"Léa","fr":"Le jeune homme qui écrit au fond, il n'est pas baptisé ?","en":"The young man writing at the back, isn't he baptized?","spans":[[47,54,"fr_baptiser_verb"]]},{"speaker":"Sophie","fr":"Pas encore. C'est un catéchumène. Il sera baptisé à Pâques.","en":"Not yet. He's a catechumen. He'll be baptized at Easter.","spans":[[21,32,"fr_catechumene_noun"],[42,49,"fr_baptiser_verb"]]},{"speaker":"Père Antoine","fr":"Et ce petit flacon, c'est l'huile pour l'onction.","en":"And this little bottle is the oil for anointing.","spans":[[41,48,"fr_onction_noun"]]},{"speaker":"Léa","fr":"L'affiche avec le pain et la coupe, c'est l'eucharistie ?","en":"The poster with the bread and the cup, is that the Eucharist?","spans":[[44,55,"fr_eucharistie_noun"]]},{"speaker":"Sophie","fr":"Oui. Monsieur Verbe vous apprend à communier : on met les mains comme ça.","en":"Yes. Monsieur Verbe is teaching you how to receive communion: you put your hands like this.","spans":[[35,44,"fr_communier_verb"]]},{"speaker":"Père Antoine","fr":"Et l'autre mime initie le petit Hugo à la cloche. Doucement !","en":"And the other mime is introducing little Hugo to the bell. Gently!","spans":[[16,22,"fr_initier_verb"]]},{"speaker":"Léa","fr":"Le globe avec les petites églises rouges, c'est pour quoi ?","en":"What's the globe with the little red churches for?","spans":[]},{"speaker":"Sophie","fr":"Pour montrer le catholicisme dans le monde entier. Ah, voilà mon filleul qui arrive sur son petit cheval en bois !","en":"To show Catholicism all over the world. Oh, here comes my godson on his little hobbyhorse!","spans":[[16,28,"fr_catholicisme_noun"],[65,72,"fr_filleul_noun"]]},{"speaker":"Père Antoine","fr":"Allez, Monsieur Verbe va bénir le goûter. À table !","en":"Come on, Monsieur Verbe is going to bless the snack. Time to eat!","spans":[[25,30,"fr_benir_verb"]]}]}],"eglise/saints":[{"id":"V_eglise_saints_01","title":"Le jour du pèlerinage","premise":"Pilgrims arrive at the saints' chapel, and Papi Henri tells Inès about the village saint.","cefr":"B1","lines":[{"speaker":"Inès","fr":"Que de roses ! Et que de monde aujourd'hui !","en":"So many roses! And so many people today!","spans":[]},{"speaker":"Papi Henri","fr":"C'est le jour du pèlerinage. Ce pèlerin avec le bâton vient de très loin.","en":"It's pilgrimage day. That pilgrim with the staff has come from very far away.","spans":[[32,39,"fr_pelerin_noun"]]},{"speaker":"Inès","fr":"Qui est le moine avec la bêche sur la tapisserie ?","en":"Who's the monk with the spade on the tapestry?","spans":[]},{"speaker":"Père Antoine","fr":"C'est notre saint du village, le moine jardinier. La tapisserie fête sa canonisation.","en":"That's our village saint, the gardener monk. The tapestry celebrates his canonization.","spans":[[12,17,"fr_saint_adj"],[72,84,"fr_canonisation_noun"]]},{"speaker":"Papi Henri","fr":"Et le vieux tableau montre une béatification, il y a très longtemps.","en":"And the old painting shows a beatification, a very long time ago.","spans":[[31,44,"fr_beatification_noun"]]},{"speaker":"Inès","fr":"Sa statue est dans la niche avec les fleurs ?","en":"Is his statue in the niche with the flowers?","spans":[]},{"speaker":"Père Antoine","fr":"Oui, c'est le sanctuaire. Les gens viennent le vénérer. Regarde Monsieur Verbe qui s'incline !","en":"Yes, that's the shrine. People come to venerate him. Look at Monsieur Verbe bowing!","spans":[[14,24,"fr_sanctuaire_noun"],[47,54,"fr_venerer_verb"]]},{"speaker":"Inès","fr":"Et l'autre mime accroche un cœur en argent au mur.","en":"And the other mime is hanging a silver heart on the wall.","spans":[]},{"speaker":"Père Antoine","fr":"Ce sont des ex-voto. On voue un cœur au saint pour dire merci.","en":"Those are votive offerings. You dedicate a heart to the saint to say thank you.","spans":[[24,28,"fr_vouer_verb"],[40,45,"fr_saint_adj"]]},{"speaker":"Papi Henri","fr":"La petite sœur donne une rose au vieux monsieur. Elle est vraiment sainte, cette femme.","en":"The little sister is giving a rose to the old man. She's truly saintly, that woman.","spans":[[67,73,"fr_saint_adj"]]},{"speaker":"Inès","fr":"Il sourit, les yeux fermés. Il a l'air bienheureux !","en":"He's smiling with his eyes closed. He looks blissful!","spans":[[39,50,"fr_bienheureux_adj"]]},{"speaker":"Père Antoine","fr":"Et sous le vitrail de l'archange, Monsieur Verbe prêche… pendant que son ami aspire les pétales avec l'aspirateur !","en":"And under the archangel window, Monsieur Verbe is preaching… while his friend vacuums up the petals!","spans":[[24,32,"fr_archange_noun"],[49,55,"fr_precher_verb"],[77,83,"fr_aspirer_verb"]]}]}],"eglise/portail":[{"id":"V_eglise_portail_01","title":"Au revoir, monsieur Martin","premise":"On a calm, sunny afternoon, Léa and Maman go to the funeral of old Monsieur Martin, their kind neighbor.","cefr":"B1","lines":[{"speaker":"Léa","fr":"Maman, pourquoi tous ces gens marchent doucement avec des fleurs blanches ?","en":"Mom, why are all those people walking slowly with white flowers?","spans":[]},{"speaker":"Maman","fr":"Ce sont les funérailles de monsieur Martin, notre gentil voisin. Il était très vieux.","en":"It's the funeral of Monsieur Martin, our kind neighbor. He was very old.","spans":[[12,23,"fr_funerailles_noun"]]},{"speaker":"Léa","fr":"Qu'est-ce qu'on écrit dans le grand livre sur la petite table ?","en":"What do people write in the big book on the little table?","spans":[]},{"speaker":"Maman","fr":"C'est le registre des obsèques. On écrit un mot gentil pour sa famille.","en":"It's the funeral guest book. You write a kind message for his family.","spans":[[22,30,"fr_obseques_noun"]]},{"speaker":"Léa","fr":"La grande boîte en bois avec les roses blanches, c'est le cercueil ?","en":"The big wooden box with the white roses, is that the coffin?","spans":[[58,66,"fr_cercueil_noun"]]},{"speaker":"Maman","fr":"Oui. Le corbillard l'a apporté jusqu'au portail. Regarde, il attend avec des fleurs.","en":"Yes. The hearse brought it to the gate. Look, it's waiting with flowers.","spans":[[8,18,"fr_corbillard_noun"]]},{"speaker":"Père Antoine","fr":"L'enterrement aura lieu là-bas, près des couronnes. Tout est calme et fleuri.","en":"The burial will take place over there, by the wreaths. Everything is calm and full of flowers.","spans":[[2,13,"fr_enterrement_noun"]]},{"speaker":"Léa","fr":"Et le jeune homme en blanc qui lit dans le livre ouvert, près du pilier ?","en":"And the young man in white reading from the open book, by the gatepost?","spans":[]},{"speaker":"Père Antoine","fr":"C'est le diacre. Il m'aide aujourd'hui : il va lire une prière pour monsieur Martin.","en":"That's the deacon. He's helping me today: he's going to read a prayer for Monsieur Martin.","spans":[[9,15,"fr_diacre_noun"]]},{"speaker":"Léa","fr":"Monsieur Verbe ramasse les lys tombés pour en faire un bouquet.","en":"Monsieur Verbe is picking up the fallen lilies to make a bouquet.","spans":[]},{"speaker":"Maman","fr":"Il les recueille pour la famille. Viens, on va se recueillir un moment.","en":"He's gathering them for the family. Come, let's take a quiet moment.","spans":[[7,16,"fr_recueillir_verb"],[50,60,"fr_recueillir_verb"]]},{"speaker":"Léa","fr":"Regarde les colombes blanches sur le muret. On dirait qu'elles sont venues lui dire au revoir.","en":"Look at the white doves on the low wall. It's as if they came to say goodbye to him.","spans":[]}]}],"eglise/sacristie":[{"id":"C_R_ch_sacristy","title":"Le nouvel enfant de chœur","premise":"The sacristan helps a boy get ready to serve at Mass for the first time.","cefr":"C2","lines":[{"speaker":"le sacristain","fr":"Bonjour Louis ! C'est ta première fois comme enfant de chœur ?","en":"Hello Louis! Is this your first time as an altar server?","spans":[[45,60,"fr_enfant_de_choeur_noun"]]},{"speaker":"Louis","fr":"Oui. Je suis un peu stressé.","en":"Yes. I'm a bit nervous.","spans":[]},{"speaker":"le sacristain","fr":"Ne t'inquiète pas. Viens dans la sacristie, je vais te donner ton aube.","en":"Don't worry. Come into the sacristy, I'll give you your alb.","spans":[[33,42,"fr_sacristie_noun"]]},{"speaker":"Louis","fr":"Elle est un peu longue !","en":"It's a bit long!","spans":[]},{"speaker":"le sacristain","fr":"Je fais un nœud avec la corde. Voilà.","en":"I'll tie it with the cord. There.","spans":[]},{"speaker":"Louis","fr":"Le père Michel met sa soutane ?","en":"Is Father Michel putting on his cassock?","spans":[[22,29,"fr_soutane_noun"]]},{"speaker":"le sacristain","fr":"Oui, et son étole verte. Toi, tu portes les burettes avec l'eau et le vin.","en":"Yes, and his green stole. You'll carry the cruets with the water and wine.","spans":[[44,52,"fr_burette_noun"]]},{"speaker":"Louis","fr":"Et l'encens ?","en":"And the incense?","spans":[[5,11,"fr_encens_noun"]]},{"speaker":"le sacristain","fr":"C'est pour les grandes fêtes. Aujourd'hui, c'est une messe simple.","en":"That's for big feast days. Today is a simple Mass.","spans":[]},{"speaker":"Louis","fr":"D'accord. Merci, monsieur le sacristain, je suis prêt !","en":"OK. Thank you, sir, I'm ready!","spans":[[29,39,"fr_sacristain_noun"]]}]},{"id":"C_R_ch_sacristy_demo","title":"La bonne couleur","premise":"The sacristan helps a young altar server get dressed before Mass.","cefr":"C2","lines":[{"speaker":"le sacristain","fr":"Tu es enfant de chœur depuis longtemps, Lucas ?","en":"Have you been an altar boy for long, Lucas?","spans":[[6,21,"fr_enfant_de_choeur_noun"]]},{"speaker":"Lucas","fr":"Depuis un mois. Je mets l'aube blanche ?","en":"For a month. Should I put on the white alb?","spans":[]},{"speaker":"le sacristain","fr":"Oui. Le prêtre porte sa soutane et son étole violette, c'est l'Avent.","en":"Yes. The priest wears his cassock and purple stole, it's Advent.","spans":[[24,31,"fr_soutane_noun"]]},{"speaker":"Lucas","fr":"Je prépare les burettes ?","en":"Should I get the cruets ready?","spans":[[15,23,"fr_burette_noun"]]},{"speaker":"le sacristain","fr":"Oui, l'eau et le vin. Ici, dans la sacristie.","en":"Yes, water and wine. Here, in the sacristy.","spans":[[35,44,"fr_sacristie_noun"]]},{"speaker":"Lucas","fr":"Et l'encens ?","en":"And the incense?","spans":[[5,11,"fr_encens_noun"]]},{"speaker":"le sacristain","fr":"Le sacristain s'en occupe : c'est moi !","en":"The sacristan takes care of it: that's me!","spans":[[3,13,"fr_sacristain_noun"]]},{"speaker":"Lucas","fr":"Ha ha ! D'accord.","en":"Ha ha! OK.","spans":[]},{"speaker":"le sacristain","fr":"Allez, la messe commence.","en":"Come on, Mass is starting.","spans":[]}]}],"eglise/chapelle":[{"id":"C_R_ch_lady_chapel","title":"Le chapelet de Mamie","premise":"A woman finds her late grandmother's rosary and asks her mother about it.","cefr":"C1","lines":[{"speaker":"Juliette","fr":"Maman, j'ai trouvé ce chapelet dans la boîte de Mamie.","en":"Mom, I found this rosary in Grandma's box.","spans":[[22,30,"fr_chapelet_noun"]]},{"speaker":"Maman","fr":"Ah, elle le priait tous les soirs. Elle avait une grande dévotion pour la Vierge.","en":"Ah, she prayed it every evening. She had a great devotion to the Virgin Mary.","spans":[[57,65,"fr_devotion_noun"],[74,80,"fr_vierge_noun"]]},{"speaker":"Juliette","fr":"Elle allait souvent à Notre-Dame, non ?","en":"She often went to Notre-Dame, didn't she?","spans":[[22,32,"fr_notre_dame_noun"]]},{"speaker":"Maman","fr":"Oui, chaque dimanche. Et à midi, elle s'arrêtait pour l'angélus, quand les cloches sonnaient.","en":"Yes, every Sunday. And at noon, she'd stop for the Angelus when the bells rang.","spans":[[56,63,"fr_angelus_noun"]]},{"speaker":"Juliette","fr":"Et le rosaire, c'est quoi la différence avec le chapelet ?","en":"And what's the difference between the rosary and the chaplet?","spans":[[6,13,"fr_rosaire_noun"],[48,56,"fr_chapelet_noun"]]},{"speaker":"Maman","fr":"Le rosaire est plus long, c'est quatre chapelets.","en":"The full rosary is longer, it's four chaplets.","spans":[[3,10,"fr_rosaire_noun"],[39,48,"fr_chapelet_noun"]]},{"speaker":"Juliette","fr":"Je vais le garder. Il y a même une petite image de l'Annonciation dans la boîte.","en":"I'll keep it. There's even a little picture of the Annunciation in the box.","spans":[[53,65,"fr_annonciation_noun"]]},{"speaker":"Maman","fr":"Elle l'avait depuis son mariage.","en":"She'd had it since her wedding.","spans":[]},{"speaker":"Juliette","fr":"Et ce cahier vierge ?","en":"And this blank notebook?","spans":[[13,19,"fr_vierge_noun"]]},{"speaker":"Maman","fr":"Elle voulait y écrire ses souvenirs. Tu pourrais le faire pour elle.","en":"She wanted to write her memories in it. You could do it for her.","spans":[]}]},{"id":"C_R_ch_lady_chapel_demo","title":"Le chapelet de grand-mère","premise":"A grandmother shows her granddaughter her rosary in the Lady Chapel.","cefr":"C1","lines":[{"speaker":"Mamie","fr":"Voici mon chapelet. Il était à ma mère.","en":"Here's my rosary. It belonged to my mother.","spans":[[10,18,"fr_chapelet_noun"]]},{"speaker":"Léa","fr":"Il est beau ! On le prie comment ?","en":"It's beautiful! How do you pray it?","spans":[]},{"speaker":"Mamie","fr":"On dit un « Je vous salue Marie » sur chaque perle. C'est le rosaire.","en":"You say a Hail Mary on each bead. That's the rosary.","spans":[[61,68,"fr_rosaire_noun"]]},{"speaker":"Léa","fr":"Et la statue, c'est la Vierge ?","en":"And the statue, is that the Virgin?","spans":[[23,29,"fr_vierge_noun"]]},{"speaker":"Mamie","fr":"Oui, Notre-Dame. Elle représente l'Annonciation.","en":"Yes, Our Lady. It shows the Annunciation.","spans":[[5,15,"fr_notre_dame_noun"],[35,47,"fr_annonciation_noun"]]},{"speaker":"Léa","fr":"Tu viens souvent ici ?","en":"Do you come here often?","spans":[]},{"speaker":"Mamie","fr":"Chaque midi, quand la cloche sonne l'angélus.","en":"Every midday, when the bell rings the Angelus.","spans":[[37,44,"fr_angelus_noun"]]},{"speaker":"Léa","fr":"Ta dévotion est touchante, Mamie.","en":"Your devotion is touching, Grandma.","spans":[[3,11,"fr_devotion_noun"]]},{"speaker":"Mamie","fr":"Merci, ma chérie.","en":"Thank you, darling.","spans":[]}]}]};
